add_action( 'template_redirect', function() {
    if ( is_admin() || wp_doing_ajax() ) {
        return;
    }
    if ( ! isset( $_GET['ref'] ) ) {
        return;
    }
    $ref_code = sanitize_text_field( wp_unslash( $_GET['ref'] ) );
    $cookie_days = apply_filters( 'terso_referral_cookie_days', 30 );
    $expires = time() + ( $cookie_days * DAY_IN_SECONDS );

    setcookie(
        'terso_ref',
        $ref_code,
        array(
            'expires'  => $expires,
            'path'     => COOKIEPATH ? COOKIEPATH : '/',
            'domain'   => COOKIE_DOMAIN,
            'secure'   => is_ssl(),
            'httponly' => true,
            'samesite' => 'Lax',
        )
    );
} );

add_action( 'woocommerce_order_status_refunded', function( $order_id ) {
    global $wpdb;
    $table_name = $wpdb->prefix . 'terso_commissions';
    $wpdb->update(
        $table_name,
        array(
            'status'     => 'rejected',
            'updated_at' => current_time( 'mysql' ),
        ),
        array(
            'order_id' => absint( $order_id ),
            'status'   => 'pending',
        ),
        array( '%s', '%s' ),
        array( '%d', '%s' )
    );
} );

public function is_self_referral( int $affiliate_user_id, string $billing_email, int $customer_user_id ): bool {
    if ( $customer_user_id > 0 && $customer_user_id === $affiliate_user_id ) {
        return true;
    }
    $affiliate_user = get_user_by( 'id', $affiliate_user_id );
    if ( $affiliate_user && strtolower( trim( $affiliate_user->user_email ) ) === strtolower( trim( $billing_email ) ) ) {
        return true;
    }
    return false;
}
